<?= $this->extend('admin/layouts/main') ?>
<?= $this->section('content') ?>
<h1 class="h3 mb-3">Automatic Order SMS</h1>
<?php if(!$configured): ?><div class="alert alert-warning">SMS sending is off. Add <code>sms.apiKey</code> to <code>.env</code> for Alpha SMS before enabling it. No customer messages are sent without a key.</div><?php endif ?>
<form class="card border-0 p-4 mb-4" method="post" action="<?= site_url('admin/sms/settings') ?>"><?= csrf_field() ?><div class="form-check form-switch mb-3"><input class="form-check-input" type="checkbox" id="smsEnabled" name="enabled" value="1" <?= ($settings['enabled']??'0')==='1'?'checked':'' ?> <?= !$configured?'disabled':'' ?>><label class="form-check-label" for="smsEnabled">Send SMS automatically on order and shipment events</label></div><p class="small text-muted">Available placeholders: <code>{order_no}</code> and <code>{track_url}</code>. Empty template disables that event.</p>
<?php foreach(['placed'=>'Order placed','confirmed'=>'Order confirmed','shipped'=>'Order shipped','delivered'=>'Order delivered','cancelled'=>'Order cancelled','shipment_booked'=>'Courier booked'] as $key=>$label): ?><div class="mb-3"><label class="form-label" for="sms-<?= $key ?>"><?= $label ?></label><textarea class="form-control" name="<?= $key ?>" id="sms-<?= $key ?>" rows="2" maxlength="500"><?= esc(old($key,$settings[$key]??'')) ?></textarea></div><?php endforeach ?><button class="btn btn-success">Save SMS settings</button></form>
<h2 class="h5 mb-3">Message log</h2><div class="card border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Order</th><th>Event</th><th>Mobile</th><th>Status</th><th>Attempts</th><th>Created</th><th></th></tr></thead><tbody><?php foreach($messages as $message): ?><tr><td>#<?= (int)$message['order_id'] ?></td><td><?= esc($message['event_type']) ?></td><td><?= esc($message['recipient_mobile']) ?></td><td><?= esc($message['status']) ?><?php if($message['last_error']): ?><small class="d-block text-danger"><?= esc($message['last_error']) ?></small><?php endif ?></td><td><?= (int)$message['attempts'] ?></td><td><?= esc($message['created_at']) ?></td><td><?php if(in_array($message['status'],['queued','failed','needs_review'],true)): ?><form method="post" action="<?= site_url('admin/sms/'.$message['id'].'/retry') ?>"><?= csrf_field() ?><?php if($message['status']==='needs_review'): ?><input type="hidden" name="confirm_unknown" value="1"><?php endif ?><button class="btn btn-sm btn-outline-primary" <?= !$configured?'disabled':'' ?> <?= $message['status']==='needs_review'?'onclick="return confirm(\'Check gateway logs first: retrying may send a duplicate SMS. Continue?\')"':'' ?>>Retry</button></form><?php endif ?></td></tr><?php endforeach ?><?php if(!$messages): ?><tr><td colspan="7" class="text-center py-4">No SMS events yet.</td></tr><?php endif ?></tbody></table></div></div><div class="mt-3"><?= $pager->links() ?></div>
<?= $this->endSection() ?>
